body{background:linear-gradient(180deg,#fff7ef,#f8e6dc);color:#4a1c2b}
.shop-page{color:#4a1c2b}.shop-page .sec-title{padding:38px 20px 30px;margin:0 auto 22px;border-radius:33px;background:linear-gradient(135deg,#b76e7922,#d4a37322);border:1px solid #ecc9c2;text-align:center}
.shop-page .sec-title h1{color:#4a1c2b}.shop-page .sec-title p{color:#8a6270}.shop-page .sec-title .kicker{color:#b76e79;font-weight:800}
